import random
random.seed(20261026)
draws = []
for _ in range(200):
    draws.append(sorted(random.sample(range(1, 46), 6)))
freq = {n: 0 for n in range(1, 46)}
for d in draws:
    for n in d:
        freq[n] += 1
top = sorted(freq.items(), key=lambda kv: (-kv[1], kv[0]))[:5]
print("Simulated draws: 200")
print("Simulated balls per draw: 6 from 1 to 45")
for n, c in top:
    print("Number " + str(n) + ": " + str(c) + " appearances in simulation")
print("Note: simulated data only, not real draw history.")

import random
random.seed(20261027)
draws = [sorted(random.sample(range(1, 46), 6)) for _ in range(100)]
def top(window):
    f = {n: 0 for n in range(1, 46)}
    for d in window:
        for n in d:
            f[n] += 1
    return sorted(f.items(), key=lambda kv: (-kv[1], kv[0]))[:3]
print("Simulated draws: 100")
print("Hot 3 in first 50 simulated draws: " + str(top(draws[:50])))
print("Hot 3 in last 50 simulated draws: " + str(top(draws[50:])))
print("Note: simulated data only, not real draw history.")
